function maxJumps(arr, d) {
  const n = arr.length;
  const memo = new Map();
  // Longest journey that starts at i, found by trying every legal jump (top-down memoised search).
  const longest = (i) => {
    if (memo.has(i)) return memo.get(i);
    let result = 1;
    for (const step of [-1, 1]) {
      let tallest = 0;
      for (let x = 1; x <= d; x++) {
        const j = i + step * x;
        if (j < 0 || j >= n) break;
        if (arr[j] < arr[i] && tallest < arr[i]) result = Math.max(result, 1 + longest(j));
        tallest = Math.max(tallest, arr[j]);
      }
    }
    memo.set(i, result);
    return result;
  };
  let answer = 0;
  for (let i = 0; i < n; i++) answer = Math.max(answer, longest(i));
  return answer;
}

