function generate(rand, size) {
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 9);
  const mode = Math.floor(rand() * 3);
  // Mode 0: few distinct heights (many ties). Mode 1: any heights. Mode 2: smooth hills, which give long journeys.
  const top = size === 'large' ? 100000 : 8;
  const arr = [];
  let height = 1 + Math.floor(rand() * top);
  for (let i = 0; i < n; i++) {
    if (mode === 0) height = 1 + Math.floor(rand() * Math.min(top, 5));
    else if (mode === 1) height = 1 + Math.floor(rand() * top);
    else height = Math.min(top, Math.max(1, height + Math.floor(rand() * 7) - 3));
    arr.push(height);
  }
  const d = 1 + Math.floor(rand() * (size === 'large' && rand() < 0.5 ? Math.min(n, 40) : n));
  return [arr, d];
}
